import sys
input = sys.stdin.read
data = input().split()

index = 0
t = int(data[index])
index += 1

results = []

for _ in range(t):
    n = int(data[index])
    index += 1

    a = list(map(int, data[index:index+n]))
    index += n
    b = list(map(int, data[index:index+n]))
    index += n
    c = list(map(int, data[index:index+n]))
    index += n

    p = []

    for i in range(n):
        if i == 0:
            if a[0] != b[1]:
                p.append(a[0])
            elif a[0] != c[1]:
                p.append(a[0])
            else:
                p.append(b[0])
        else:
            if p[-1] != a[i]:
                p.append(a[i])
            elif p[-1] != b[i]:
                p.append(b[i])
            else:
                p.append(c[i])

    results.append(p)

for result in results:
    print(" ".join(map(str, result)))
